# Let's manually analyze the differences
inputs = ['fkfe', 'xhfky', 'ckvc', 'kkw', 'bykau']
outputs = ['fkgfe', 'xhfkgh', 'ckghdjc', 'kgkgdkg', 'bhehu']

# Analyze each transformation
for i in range(len(inputs)):
    orig = inputs[i]
    target = outputs[i]
    print(f"\n{i}: '{orig}' -> '{target}'")

    # Find where they differ
    min_len = min(len(orig), len(target))
    diff_pos = -1
    for j in range(min_len):
        if orig[j] != target[j]:
            diff_pos = j
            break

    if diff_pos == -1:
        if len(orig) != len(target):
            diff_pos = min_len

    if diff_pos != -1:
        print(f"  First difference at position {diff_pos}")
        if diff_pos < len(orig) and diff_pos < len(target):
            print(f"  Character '{orig[diff_pos]}' -> '{target[diff_pos]}'")
        elif diff_pos >= len(orig):
            print(f"  Added character '{target[diff_pos]}' at end")
        else:
            print(f"  Removed character at position {diff_pos}")
    else:
        print("  No differences found")

